<?php
$cartTotal = array_sum(array_map(static fn (array $item): float => (float)$item['price'], $cartItems));
?>
<section class="swap-page cart-page"><div class="sub-header"><a href="?page=home">←</a><b>Shopping Cart</b><span></span></div><p class="eyebrow">YOUR ITEMS</p><?php if (!$cartItems): ?><div class="empty-page"><div class="empty-icon">□</div><h1>Your cart is empty</h1><p>Add something you love and it will appear here.</p><a class="primary" href="?page=home">Browse items</a></div><?php else: ?><div class="cart-items"><?php foreach ($cartItems as $item): ?><article class="cart-item"><img src="<?= e(image_for($item)) ?>" alt="<?= e($item['title']) ?>"><div><b><?= e($item['title']) ?></b><small><?= e($item['size']) ?> · <?= e($item['item_condition']) ?></small><strong>$<?= number_format((float)$item['price'], 2) ?></strong><form method="post"><input type="hidden" name="action" value="remove_from_cart"><input type="hidden" name="listing_id" value="<?= (int)$item['id'] ?>"><button class="text-button">Remove</button></form></div></article><?php endforeach; ?></div><div class="order-total"><div><span>Subtotal</span><b>$<?= number_format($cartTotal, 2) ?></b></div><div><span>Shipping</span><b>$<?= number_format(count($cartItems) * 6, 2) ?></b></div><div class="total-row"><span>Total</span><b>$<?= number_format($cartTotal + count($cartItems) * 6, 2) ?></b></div></div><a class="primary cart-checkout" href="?page=payment&id=<?= (int)$cartItems[0]['id'] ?>">Checkout</a><?php endif; ?></section>